import sys
from collections import defaultdict

def manacher(s):
    n = len(s)
    lps = [0] * n
    center = right = 0
    for i in range(n):
        mirror = 2 * center - i
        if i < right:
            lps[i] = min(right - i, lps[mirror])
        while i + lps[i] + 1 < n and i - lps[i] - 1 >= 0 and s[i + lps[i] + 1] == s[i - lps[i] - 1]:
            lps[i] += 1
        if i + lps[i] > right:
            center = i
            right = i + lps[i]
    return lps

def count_palindromes(s):
    n = len(s)
    lps_odd = manacher(s)
    lps_even = manacher('#' + '#'.join(s) + '#')
    palindromes = set()
    for i in range(n):
        for j in range(i - lps_odd[i], i + lps_odd[i] + 1, 2):
            palindromes.add(s[j//2:(i+lps_odd[i]+1)//2])
        for j in range(2 * i - lps_even[i], 2 * i + lps_even[i] + 2, 2):
            palindromes.add(s[j//2:(2*i+lps_even[i]+2)//2])
    return palindromes

def count_distinct_decorations(T, N):
    palindromes = count_palindromes(T)
    dp = [[0] * (N + 1) for _ in range(len(palindromes) + 1)]
    dp[0][0] = 1
    for i in range(1, len(palindromes) + 1):
        dp[i][0] = 1
        for j in range(1, N + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(j):
                dp[i][j] += dp[i - 1][k]
    return sum(dp[len(palindromes)][j] for j in range(1, N + 1)) % (10**9 + 7)

def main():
    import sys
    input = sys.stdin.read().split()
    T = input[0]
    N = int(input[1])
    print(count_distinct_decorations(T, N))

main()
